export const REFUND_SUB_CELLS = ["REF-a", "REF-b", "REF-c"] as const;
export type RefundSubCell = typeof REFUND_SUB_CELLS[number];
export const REFUND_REQUIREMENT_IDS: Record<RefundSubCell, string[]> = {
  "REF-a": ["FR-13"],
  "REF-b": ["FR-13"],
  "REF-c": ["FR-13"],
};

export function cellId(intent: Intent, scenario: Scenario, currency: Currency): string {
  return `PAY-${intent}-${scenario}-${currency}`;
}
